typedef char Elemtype;
int bracketmatching()
{
    SqStack S;
    Elemtype ch;
    InitStack(S);
    while ((ch=getchar())!='\n')
    {
    switch (ch)    //遇左括号入栈;遇到右括号时,分别检测匹配情况
    {
    case '(':
    case '[':
    case '{: 
    Push(S,ch);break;
    case ')':
    if (StackEmpty(S)) return FALSE;
    else 
    { Pop(S,ch); if (ch != '(') return FALSE; }
    break;
    case ' '}':
    if (StackEmpty(S)) return FALSE;
    else 
    { Pop(S,ch); if (ch != '[') return FALSE; }
    break;
    case '}':
    if (StackEmpty(S)) return FALSE;
    else
{ Pop(S,ch); if (ch!='{'}) return FALSE; }
    break;
    default:break;
}
if (StackEmpty(S)) return TRUE;
else return FALSE;
}
